CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"04d1bcc9-31d6-5ac7-853e-c658c52eab3f","source_id":"2208","name_en":"roller back stretch","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0644\u0623\u0633\u0637\u0648\u0627\u0646\u0629 \u0627\u0644\u062e\u0644\u0641\u064a\u0629","match_names":["roller back stretch"],"muscle":"back","equipment":"roller","aliases":["roller back stretch"],"logging_mode":"timed","load_convention":"external_total","guidance":{"steps_en":"Start by sitting on the ground with your legs extended in front of you.\nPlace the roller perpendicular to your body, just below your glutes.\nSlowly roll your body backwards, allowing the roller to move up your back.\nContinue rolling until the roller reaches your upper back.\nPause for a moment, then slowly roll back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u062c\u0644\u0648\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0636\u0639 \u0627\u0644\u0623\u0633\u0637\u0648\u0627\u0646\u0629 \u0628\u0634\u0643\u0644 \u0639\u0645\u0648\u062f\u064a \u0639\u0644\u0649 \u062c\u0633\u0645\u0643\u060c \u0623\u0633\u0641\u0644 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0642\u0645 \u0628\u0644\u0641 \u062c\u0633\u0645\u0643 \u0644\u0644\u062e\u0644\u0641 \u0628\u0628\u0637\u0621\u060c \u0645\u0645\u0627 \u064a\u0633\u0645\u062d \u0644\u0644\u0623\u0633\u0637\u0648\u0627\u0646\u0629 \u0628\u0627\u0644\u062a\u062d\u0631\u0643 \u0644\u0623\u0639\u0644\u0649 \u0638\u0647\u0631\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u062f\u062d\u0631\u062c \u062d\u062a\u0649 \u062a\u0635\u0644 \u0627\u0644\u0623\u0633\u0637\u0648\u0627\u0646\u0629 \u0625\u0644\u0649 \u0623\u0639\u0644\u06