roller side lat stretch"],"muscle":"back","equipment":"roller","aliases":["roller side lat stretch"],"logging_mode":"timed","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.\nBend your knees slightly and hinge forward at the hips, keeping your back straight.\nExtend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.\nHold the stretch for a few seconds, then slowly roll the roller back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0627\u0645\u0633\u0643 \u0627\u0644\u0623\u0633\u0637\u0648\u0627\u0646\u0629 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0623\u0645\u0627\u0645 \u062c\u0633\u0645\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0648\u0644\u0641 \u0627\u0644\u0623\u0633\u0637\u0648\u0627\u0646\u0629 \u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0642\u062f\u0645\u064a\u0643\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0639\u0636\u0644\u0627\u062a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0642\u0645 \u0628\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0623\u0633\u0637\u0648\u0627\u0646\u0629 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2207","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2207-c3Pfhti.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2207-c3Pfhti.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"90cdd195-f2b2-5a90-8e9d-71ba5065c8b5","source_id":"0680","name_en":"rope climb","name_ar":"\u062a\u0633\u0644\u0642 \u0627\u0644\u062d\u0628\u0644","match_names":["rope climb"],"muscle":"back","equipment":"rope","aliases":["rope climb"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand facing the rope with your feet shoulder-width apart.\nGrab the rope with both hands, palms facing towards you.\nBend your knees slightly and engage your core.\nBegin pulling yourself up the rope by alternating hand-over-hand movements.\nUse your legs to assist in the upward movement.\nContinue climbing until you reach the desired height or the top of the rope.\nTo descend, reverse the hand-over-hand movement while controlling your descent.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u062d\u0628\u0644 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0646\u062d\u0648\u0643.\n\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627 \u0648\u0627\u0634\u0631\u0643 \u0642\u0644\u0628\u0643.\n\u0627\u0628\u062f\u0623 \u0628\u0633\u062d\u0628 \u0646\u0641\u0633\u0643 \u0644\u0623\u0639\u0644\u0649 \u0627\u0644\u062d\u0628\u0644 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u062d\u0631\u0643\u0627\u062a \u0627\u0644\u064a\u062f.\n\u0627\u0633\u062a\u062e\u062f\u0645 \u0633\u0627\u0642\u064a\u0643 \u0644\u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0641\u064a \u0627\u0644\u062d\u0631\u0643\u0629 \u0627\u0644\u0635\u0639\u0648\u062f\u064a\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0633\u0644\u0642 \u062d\u062a\u0649 \u062a\u0635\u0644 \u0625\u0644\u0649 \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0623\u0648 \u0642\u0645\u0629 \u0627\u0644\u062d\u0628\u0644.\n\u0644\u0644\u0646\u0632\u0648\u0644\u060c \u0642\u0645 \u0628\u0639\u0643\u0633 \u062d\u0631\u0643\u0629 \u0627\u0644\u064a\u062f \u0645\u0639 \u0627\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u0627\u0644\u0646\u0632\u0648\u0644.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4