644\u0645\u0637\u0644\u0648\u0628\u0629.\n\u062a\u0630\u0643\u0631 \u0623\u0646 \u062a\u062a\u0646\u0641\u0633 \u0628\u0639\u0645\u0642 \u0648\u062a\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u062c\u064a\u062f\u0629 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0684","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0684-y5p0H8a.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0684-y5p0H8a.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6de1464c-6b64-55c4-8bad-83b79fd25857","source_id":"1585","name_en":"runners stretch","name_ar":"\u0627\u0644\u0639\u062f\u0627\u0626\u064a\u0646 \u062a\u0645\u062a\u062f","match_names":["runners stretch"],"muscle":"hamstrings","equipment":"bodyweight","aliases":["runners stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet hip-width apart.\nTake a step forward with your right foot, keeping your left foot planted.\nBend your right knee and lower your body down, keeping your left leg straight.\nPlace your hands on your right thigh for support.\nHold the stretch for 20-30 seconds, then switch sides and repeat.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0639\u0631\u0636 \u0645\u0641\u0635\u0644 \u0627\u0644\u0648\u0631\u0643.\n\u062e\u0630 \u062e\u0637\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u062b\u0627\u0628\u062a\u0629.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0633\u0641\u0644\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0641\u062e\u0630\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0648\u0643\u0631\u0631 \u0627\u0644\u0623\u0645\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1585","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["calves","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1585-0mB6wHO.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1585-0mB6wHO.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f804b54c-020a-53b1-8852-67b7eaeea65d","source_id":"0687","name_en":"russian twist","name_ar":"\u062a\u0637\u0648\u0631 \u0631\u0648\u0633\u064a","match_names":["russian twist"],"muscle":"core","equipment":"bodyweight","aliases":["russian twist"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the ground with your knees bent and feet flat on the floor.\nLean back slightly while keeping your back straight and your core engaged.\nHold your hands together in front of your chest or hold a weight if desired.\nLift your feet off the ground, balancing on your sit bones.\nTwist your torso to the right, bringing your hands or weight towards the right side of your body.\nPause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0646\u062d\u0646\u0650 \u0644\u0644\u062e\u0644\u0641 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0625\u0634\u0631\u0627\u0643 \u062c\u0630\u0639\u0643.\n\u0627\u062c\u0645\u0639 \u064a\u062f\u064a\u0643 \u0645\u0639\u064b\u0627 \u0623\u0645\u0627\u0645 \u0635\u062f\u0631\u0643 \u0623\u0648 \u0627\u062d\u0645\u0644 \u0648\u0632\u0646\u064b\u0627 \u0625\u0630\u0627 \u0631\u063a\u0628\u062a \u0641\u064a \u0630\u0644\u0643.\n\u0627\u0631\u0641\u0639\u064a \u0642\u062f\u0645\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062a\u0648\u0627\u0632\u0646 \u0639\u0644\u0649 \u0639\u0638\u0627\u0645 \u0627\u0644\u062c\u0644\u0648\u0633.\n\u0642\u0645 \u0628\u0644\u0641 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0623\u0648 \u0648\u0632\u0646\u0643 \u0646\u062d\u0648 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0623\u064a\u0645\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u0644\u0641 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631\u060c \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0623\u0648 \u0648\u0632\u0646\u0643 \u0646\u062d\u0648 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0623\u064a\u0633\u0631 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0687","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0687-XVDdcoj.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0687-XVDdcoj.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b7b189a5-dcfc-549f-8df1-f8eb9060da21","source_id":"3012","name_en":"scapula dips","name_ar":"\u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636\u0627\u062a \u0644\u0648\u062d \u0627\u0644\u0643\u062a\u0641","match_names":["scapula dips"],"muscle":"back","equipment":"bodyweight","aliases":["scapula dips"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by standing with your feet shoulder-width apart and your arms extended in front of you.\nBend your knees slightly and hinge forward at the hips, keeping your back straight.\nLower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.\nPause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u0633\u062d\u0628 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643\u060c \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u062d\u0627\u0648\u0644 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0642\u0644\u0645 \u0631\u0635\u0627\u0635 \u0628\u064a\u0646\u0647\u0645\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0628\u064a\u062f\u064a\u0643 \u0644\u062a\u0645\u062f\u064a\u062f \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3012","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"traps","secondary_muscles":["rhomboids","deltoids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3012-7xeukSt.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3012-7xeukSt.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8fd450e4-61f9-5f51-80a8-80165252faeb","source_id":"3021","name_en":"scapula push-up","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d \u0627\u0644\u0643\u062a\u0641","match_names":["scapula push-up"],"muscle":"serratus_anterior","equipment":"bodyweight","aliases":["scapula push-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a high plank position with your hands directly under your shoulders and your body in a straight line.\nLower your chest towards the ground, keeping your elbows close to your body.\nAs you lower, squeeze your shoulder blades together and push your chest forward.\nPause for a moment at the bottom, then push back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u062a \u0643\u062a\u0641\u064a\u0643 \u0648\u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0627\u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0628\u064a\u0646\u0645\u0627 \u062a\u0646\u0632\u0644\u060c \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0648\u0627\u062f\u0641\u0639 \u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0644\u0644\u0623\u0639\u0644\u0649 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3021","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"serratus anterior","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3021-jV65tKx.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3021-jV65tKx.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"18c6240c-b3bf-5384-849f-d1414b923a4d","source_id":"0688","name_en":"scapular pull-up","name_ar":"\u0633\u062d\u0628 \u0643\u062a\u0641\u064a","match_names":["scapular pull-up"],"muscle":"back","equipment":"bodyweight","aliases":["scapular pull-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.\nRetract your shoulder blades by pulling them down and back.\nEngage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.\nPause for a moment at the top of the movement, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0627\u0633\u062d\u0628 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0633\u062d\u0628\u0647\u0645\u0627 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0644\u0644\u062e\u0644\u0641.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643 \u0648\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0628\u0627\u0631\u060c \u0645\u0639 \u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0639\u0644\u0649 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0688","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"traps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0688-uTBt1HV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0688-uTBt1HV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c01f9647-977c-53b0-83ae-248d87e4951a","source_id":"3219","name_en":"scissor jumps (male)","name_ar":"\u0627\u0644\u0642\u0641\u0632 \u0628\u0627\u0644\u0645\u0642\u0635 (\u0630\u0643\u0631)","match_names":["scissor jumps (male)"],"muscle":"cardio","equipment":"bodyweight","aliases":["scissor jumps (male)"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nJump off the ground and simultaneously cross your right leg in front of your left leg.\nAs you land, quickly switch legs, crossing your left leg in front of your right leg.\nContinue alternating legs and jumping as quickly as possible.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0642\u0641\u0632 \u0645\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a \u0627\u0639\u0628\u0631 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0623\u0645\u0627\u0645 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0623\u062b\u0646\u0627\u0621 \u0647\u0628\u0648\u0637\u0643\u060c \u0628\u062f\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0633\u0631\u0639\u0629\u060c \u0645\u0639 \u0648\u0636\u0639 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0623\u0645\u0627\u0645 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0623\u0631\u062c\u0644 \u0648\u0627\u0644\u0642\u0641\u0632 \u0628\u0623\u0633\u0631\u0639 \u0645\u0627 \u064a\u0645\u0643\u0646.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3219","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3219-Eh2v5Iu.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3219-Eh2v5Iu.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1267cd13-53a6-574c-8a37-c40ef714adcf","source_id":"1390","name_en":"seated calf stretch (male)","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u062a\u0645\u062f\u062f \u0627\u0644\u0633\u0627\u0642 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062c\u0644\u0648\u0633 (\u0630\u0643\u0631)","match_names":["seated calf stretch (male)"],"muscle":"calves","equipment":"bodyweight","aliases":["seated calf stretch (male)"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the edge of a chair or bench with your feet flat on the ground.\nExtend one leg straight out in front of you, keeping your heel on the ground.\nLean forward slightly, feeling a stretch in your calf muscle.\nHold the stretch for 20-30 seconds.\nSwitch legs and repeat the stretch.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u0643\u0631\u0633\u064a \u0623\u0648 \u0627\u0644\u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0645\u062f \u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629 \u0623\u0645\u0627\u0645\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0642\u0644\u064a\u0644\u064b\u0627\u060c \u0648\u0633\u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0639\u0636\u0644\u0629 \u0627\u0644\u0633\u0627\u0642.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0648\u0643\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1390","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1390-17bqEXD.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1390-17bqEXD.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5d9e12dc-2c87-56c1-8dcf-d5f8081ed296","source_id":"1424","name_en":"seated glute stretch","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0644\u0623\u0644\u0648\u064a\u0629 \u062c\u0627\u0644\u0633\u0627","match_names":["seated glute stretch"],"muscle":"glutes","equipment":"bodyweight","aliases":["seated glute stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the ground with your legs extended in front of you.\nBend your right knee and cross your right ankle over your left thigh.\nPlace your right hand on the ground behind you for support.\nWith your left hand, gently press down on your right knee to deepen the stretch.\nHold the stretch for 30 seconds to 1 minute.\nSwitch sides and repeat.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0639\u0628\u0631 \u0627\u0644\u0643\u0627\u062d\u0644 \u0627\u0644\u0623\u064a\u0645\u0646 \u0639\u0644\u0649 \u0641\u062e\u0630\u0643 \u0627\u0644\u0623\u064a\u0633\u0631.\n\u0636\u0639 \u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u062e\u0644\u0641\u0643 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649\u060c \u0627\u0636\u063a\u0637 \u0628\u0644\u0637\u0641 \u0639\u0644\u0649 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0644\u062a\u0639\u0645\u064a\u0642 \u0627\u0644\u062a\u0645\u062f\u062f.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0625\u0637\u0627\u0644\u0629 \u0644\u0645\u062f\u0629 30 \u062b\u0627\u0646\u064a\u0629 \u0625\u0644\u0649 1 \u062f\u0642\u064a\u0642\u0629.\n\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0648\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1424","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1424-DeDThfG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1424-DeDThfG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"14bb8b8d-8ae9-5dbf-8d35-49522a03d57c","source_id":"0689","name_en":"seated leg raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0633\u0627\u0642 \u062c\u0627\u0644\u0633\u0627","match_names":["seated leg raise"],"muscle":"core","equipment":"bodyweight","aliases":["seated leg raise"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on a flat bench with your back straight and your feet flat on the ground.\nPlace your hands on the sides of the bench for support.\nKeeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.\nPause for a moment at the top, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0633\u0637\u062d \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0627\u0644\u0645\u0642\u0639\u062f \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u0627\u0631\u0641\u0639\u064a\u0647\u0645\u0627 \u0628\u0628\u0637\u0621 \u0623\u0645\u0627\u0645\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0689","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0689-Hgs6Nl1.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0689-Hgs6Nl1.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"950bcf86-a69b-550c-883a-c022f751dd2d","source_id":"0690","name_en":"seated lower back stretch","name_ar":"\u064a\u062c\u0644\u0633 \u0623\u0633\u0641\u0644 \u0627\u0644\u0638\u0647\u0631 \u062a\u0645\u062a\u062f","match_names":["seated lower back stretch"],"muscle":"back","equipment":"bodyweight","aliases":["seated lower back stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the edge of a chair with your feet flat on the ground.\nPlace your hands on your thighs or on the sides of the chair for support.\nSlowly lean forward from your hips, keeping your back straight.\nFeel the stretch in your lower back and hold for 20-30 seconds.\nSlowly return to the starting position and repeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u0643\u0631\u0633\u064a \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643 \u0623\u0648 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0627\u0644\u0643\u0631\u0633\u064a \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0627\u0646\u062d\u0646\u064a \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0645\u0646 \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u062d\u0627\u0641\u0638\u064a \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u0634\u0639\u0631 \u0628\u0627\u0644\u062a\u0645\u062f\u062f \u0641\u064a \u0623\u0633\u0641\u0644 \u0638\u0647\u0631\u0643 \u0648\u0627\u0633\u062a\u0645\u0631 \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0690","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["glutes","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0690-QFmz6ch.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0690-QFmz6ch.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bfc17f3d-c401-5369-8b43-9eb9c1a640f4","source_id":"2567","name_en":"seated piriformis stretch","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0644\u0643\u0645\u062b\u0631\u064a \u062c\u0627\u0644\u0633\u0627","match_names":["seated piriformis stretch"],"muscle":"glutes","equipment":"bodyweight","aliases":["seated piriformis stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the ground with your legs extended in front of you.\nBend your right knee and place your right foot on the outside of your left knee.\nPlace your left elbow on the outside of your right knee and gently twist your torso to the right.\nHold the stretch for 20-30 seconds, then switch sides and repeat.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0636\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u0645\u0646 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0636\u0639 \u0643\u0648\u0639\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u0645\u0646 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0641 \u062c\u0630\u0639\u0643 \u0628\u0644\u0637\u0641 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0648\u0643\u0631\u0631 \u0627\u0644\u0623\u0645\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2567","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2567-QY39eBr.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2567-QY39eBr.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9481d704-6136-5515-8513-81e22fc4695e","source_id":"0691","name_en":"seated side crunch (wall)","name_ar":"\u0623\u0632\u0645\u0629 \u062c\u0627\u0646\u0628\u064a\u0629 \u062c\u0627\u0644\u0633\u0629 (\u0627\u0644\u062c\u062f\u0627\u0631)","match_names":["seated side crunch (wall)"],"muscle":"core","equipment":"bodyweight","aliases":["seated side crunch (wall)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the floor with your back against a wall and your legs extended in front of you.\nBend your knees and place your feet flat on the floor, hip-width apart.\nPlace your hands behind your head with your elbows pointing outwards.\nEngage your abs and lean to one side, bringing your elbow towards your hip.\nPause for a moment, then return to the starting position.\nRepeat on the other side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637 \u0648\u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u062e\u0627\u0631\u062c.\n\u0642\u0645 \u0628\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0627\u0646\u062d\u0646\u064a \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f\u060c \u0648\u062c\u0644\u0628 \u0645\u0631\u0641\u0642\u0643 \u0646\u062d\u0648 \u0648\u0631\u0643\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0691","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0691-Y9hNPcN.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0691-Y9hNPcN.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7201c814-3c92-5f05-859d-6ee1159e6924","source_id":"1587","name_en":"seated wide angle pose sequence","name_ar":"\u062a\u0633\u0644\u0633\u0644 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u062c\u0644\u0648\u0633 \u0628\u0632\u0627\u0648\u064a\u0629 \u0648\u0627\u0633\u0639\u0629","match_names":["seated wide angle pose sequence"],"muscle":"hamstrings","equipment":"bodyweight","aliases":["seated wide angle pose sequence"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the ground with your legs extended in a wide angle.\nFlex your feet and engage your quadriceps.\nPlace your hands on the ground behind you for support.\nKeeping your back straight, lean forward from your hips.\nContinue leaning forward until you feel a stretch in your hamstrings.\nHold this position for a few breaths.\nSlowly release the stretch and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 \u0648\u0627\u0633\u0639\u0629.\n\u062b\u0646\u064a \u0642\u062f\u0645\u064a\u0643 \u0648\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0641\u062e\u0630.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u062e\u0644\u0641\u0643 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643\u060c \u0648\u0627\u0646\u062d\u0646 \u0644\u0644\u0623\u0645\u0627\u0645 \u0645\u0646 \u0648\u0631\u0643\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0645\u064a\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629.\n\u0634\u063a\u0644 \u0647\u0630\u0627 \u0627\u0644\u0645\u0646\u0635\u0628 \u0644\u0628\u0636\u0639\u0629 \u0623\u0646\u0641\u0627\u0633.\n\u062d\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f \u0628\u0628\u0637\u0621 \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revisi