["side lying floor stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Lie on your side with your legs straight and your bottom arm extended straight overhead.\nBend your top knee and place your foot on the ground in front of your bottom leg.\nReach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.\nSlowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.\nHold the stretch for 20-30 seconds, then slowly lower your leg back down.\nRepeat on the other side.","steps_ar":"\u0627\u0633\u062a\u0644\u0642 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u0643 \u0645\u0639 \u0641\u0631\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0645\u062f\u0648\u062f \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u0629 \u0648\u0636\u0639 \u0642\u062f\u0645\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645 \u0633\u0627\u0642\u0643 \u0627\u0644\u0633\u0641\u0644\u064a\u0629.\n\u0636\u0639 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u0641\u0648\u0642 \u0631\u0623\u0633\u0643 \u0648\u0627\u0645\u0633\u0643 \u0628\u0634\u064a\u0621 \u062b\u0627\u0628\u062a\u060c \u0645\u062b\u0644 \u062c\u062f\u0627\u0631 \u0623\u0648 \u0642\u0637\u0639\u0629 \u0623\u062b\u0627\u062b.\n\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u0643 \u0627\u0644\u0633\u0641\u0644\u064a\u0629 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u0629\u060c \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u062c\u0627\u0646\u0628\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0633\u0627\u0642\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644.\n\u0643\u0631\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1358","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["obliques","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1358-jDOKRM5.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1358-jDOKRM5.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"32893305-d0a8-53ab-82e2-8ead5edc8416","source_id":"3667","name_en":"side lying hip adduction (male)","name_ar":"\u062a\u0642\u0631\u064a\u0628 \u0627\u0644\u0648\u0631\u0643 \u0645\u0633\u062a\u0644\u0642\u064a\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 (\u0630\u0643\u0631)","match_names":["side lying hip adduction (male)"],"muscle":"adductors","equipment":"bodyweight","aliases":["side lying hip adduction (male)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie on your side with your legs straight and stacked on top of each other.\nPlace your bottom arm under your head for support.\nEngage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.\nPause for a moment at the top, then slowly lower your leg back down to the starting position.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u0643 \u0645\u0639 \u0648\u0636\u0639 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646 \u0648\u0645\u0643\u062f\u0633\u062a\u064a\u0646 \u0641\u0648\u0642 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0636\u0639 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0633\u0641\u0644\u064a \u062a\u062d\u062a \u0631\u0623\u0633\u0643 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0645\u0642\u0631\u0628\u064a\u0646 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u0643 \u0627\u0644\u0639\u0644\u064a\u0627 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646 \u062f\u0648\u0646 \u062a\u062f\u0648\u064a\u0631 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0623\u0648 \u0627\u0644\u0645\u064a\u0644 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3667","license":"MIT"},"translation":{"provider":"Google T