u064a\u0646 \u0641\u0648\u0642 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0627\u0633\u0646\u062f \u0646\u0641\u0633\u0643 \u0639\u0644\u0649 \u0633\u0627\u0639\u062f\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u0643 \u0623\u0633\u0641\u0644 \u0643\u062a\u0641\u0643 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0645\u0627 \u064a\u062e\u0644\u0642 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0625\u0644\u0649 \u0642\u062f\u0645\u064a\u0643.\n\u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u060c \u0627\u0631\u0641\u0639\u064a \u0633\u0627\u0642\u0643 \u0627\u0644\u0639\u0644\u064a\u0627 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0633\u0627\u0642\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1775","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"adductors","secondary_muscles":["obliques","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1775-VO2qeJg.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1775-VO2qeJg.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ce7f04d3-15c2-57a1-8e47-bb7d17c6d56b","source_id":"0716","name_en":"side push neck stretch","name_ar":"\u062a\u0645\u062f\u062f \u0627\u0644\u0631\u0642\u0628\u0629 \u0628\u0627\u0644\u062f\u0641\u0639 \u0627\u0644\u062c\u0627\u0646\u0628\u064a","match_names":["side push neck stretch"],"muscle":"levator_scapulae","equipment":"bodyweight","aliases":["side push neck stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand or sit up straight with your shoulders relaxed.\nTilt your head to the right, bringing your right ear towards your right shoulder.\nPlace your right hand on the left side of your head and gently apply pressure to increase the stretch.\nHold the stretch for 15-30 seconds.\nRepeat on the other side, tilting your head to the left and applying pressure with your left hand.\nRepeat the stretch 2-3 times on each side.","steps_ar":"\u0642\u0641 \u0623\u0648 \u0627\u062c\u0644\u0633 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0627\u0633\u062a\u0631\u062e\u0627\u0621 \u0643\u062a\u0641\u064a\u0643.\n\u0642\u0645 \u0628\u0625\u0645\u0627\u0644\u0629 \u0631\u0623\u0633\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0648\u062c\u0644\u0628 \u0623\u0630\u0646\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643 \u0627\u0644\u0623\u064a\u0645\u0646.\n\u0636\u0639 \u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0623\u064a\u0633\u0631 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0648\u0642\u0645 \u0628\u0627\u0644\u0636\u063a\u0637 \u0628\u0644\u0637\u0641 \u0644\u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u062a\u0645\u062f\u062f.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 15-30 \u062b\u0627\u0646\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631\u060c \u0645\u0639 \u0625\u0645\u0627\u0644\u0629 \u0631\u0623\u0633\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631 \u0648\u0627\u0644\u0636\u063a\u0637 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0643\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f 2-3 \u0645\u0631\u0627\u062a \u0639\u0644\u0649 \u0643\u0644 \u062c\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0716","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"levator scapulae","secondary_muscles":["trapezius","sternocleidomastoid"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0716-oQRJYkC.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0716-oQRJYkC.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4afb0326-7f1b-5802-8fc0-bbdfb3356dc3","source_id":"0717","name_en":"side push-up","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u062c\u0627\u0646\u0628\u064a","match_names":["side push-up"],"muscle":"triceps","equipment":"bodyweight","aliases":["side push-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by lying on your side with your legs extended and stacked on top of each other.\nPlace your bottom hand on the ground directly under your shoulder, fingers pointing forward.\nPress through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.\nExtend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.\nLower your body back down to the starting position with control.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0645\u0643\u062f\u0633\u062a\u064a\u0646 \u0641\u0648\u0642 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0636\u0639 \u064a\u062f\u0643 \u0627\u0644\u0633\u0641\u0644\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u062a \u0643\u062a\u0641\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u064a\u062f\u0643 \u0627\u0644\u0633\u0641\u0644\u064a\u0629 \u0644\u0631\u0641\u0639 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0633\u0627\u0642\u064a\u0643 \u0648\u062c\u0630\u0628 \u062c\u0630\u0639\u0643.\n\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641\u060c \u0645\u0645\u0627 \u064a\u0634\u0643\u0644 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0625\u0644\u0649 \u0643\u0639\u0628\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0645\u0639 \u0627\u0644\u062a\u062d\u0643\u0645.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0717","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders","chest","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0717-wpbD28t.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0717-wpbD28t.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"51a171d8-01fd-5961-8cc5-b4e9756b4d3e","source_id":"0721","name_en":"side wrist pull stretch","name_ar":"\u062a\u0645\u062a\u062f \u0633\u062d\u0628 \u0627\u0644\u0645\u0639\u0635\u0645 \u0627\u0644\u062c\u0627\u0646\u0628\u064a","match_names":["side wrist pull stretch"],"muscle":"forearms","equipment":"bodyweight","aliases":["side wrist pull stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your arms extended in front of you.\nExtend your right arm out to the side, parallel to the ground, with your palm facing down.\nWith your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.\nHold the stretch for 15-30 seconds, then release.\nRepeat on the other side.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u060c \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0623\u0633\u0641\u0644.\n\u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649\u060c \u0623\u0645\u0633\u0643 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u0633\u062d\u0628\u0647\u0627 \u0628\u0644\u0637\u0641 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0633\u0627\u0639\u062f\u0643 \u0627\u0644\u0623\u064a\u0645\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 15-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0627\u062a\u0631\u0643\u0647.\n\u0643\u0631\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0721","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["wrists","hands"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0721-UtmIqcI.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0721-UtmIqcI.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c60cba45-3c7d-5b27-8910-e60b8df14586","source_id":"0720","name_en":"side-to-side chin","name_ar":"\u0627\u0644\u0630\u0642\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628","match_names":["side-to-side chin"],"muscle":"back","equipment":"bodyweight","aliases":["side-to-side chin"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your knees slightly bent.\nGrasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.\nHang from the bar with your arms fully extended and your body relaxed.\nPull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.\nOnce your chin is above the bar, lower yourself back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0634\u0646\u0642 \u0645\u0646 \u0627\u0644\u0628\u0627\u0631 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0627\u0633\u062a\u0631\u062e\u0627\u0621 \u062c\u0633\u0645\u0643.\n\u0627\u0633\u062d\u0628 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062a\u0648\u062c\u064a\u0647 \u0630\u0642\u0646\u0643 \u0646\u062d\u0648 \u0627\u0644\u0628\u0627\u0631\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u062c\u0633\u0645\u0643.\n\u0628\u0645\u062c\u0631\u062f \u0623\u0646 \u062a\u0635\u0628\u062d \u0630\u0642\u0646\u0643 \u0641\u0648\u0642 \u0627\u0644\u0634\u0631\u064a\u0637\u060c \u0642\u0645 \u0628\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0720","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0720-isAAZWA.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0720-isAAZWA.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a2e7db8b-b6aa-579d-87a5-eba5492f8f92","source_id":"3213","name_en":"side-to-side toe touch (male)","name_ar":"\u0644\u0645\u0633 \u0625\u0635\u0628\u0639 \u0627\u0644\u0642\u062f\u0645 \u062c\u0646\u0628\u064b\u0627 \u0625\u0644\u0649 \u062c\u0646\u0628 (\u0630\u0643\u0631)","match_names":["side-to-side toe touch (male)"],"muscle":"core","equipment":"bodyweight","aliases":["side-to-side toe touch (male)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your arms extended to the sides.\nBend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.\nReturn to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.\nRepeat the side-to-side bending motion for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u0627\u0646\u062d\u0646\u0649 \u0639\u0646\u062f \u0627\u0644\u062e\u0635\u0631 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0628\u062d\u064a\u062b \u062a\u0635\u0644 \u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0646\u062d\u0648 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0645\u0645\u062a\u062f\u0629 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628.\n\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u062b\u0645 \u0627\u0646\u062d\u0646\u0649 \u0639\u0646\u062f \u0627\u0644\u062e\u0635\u0631 \u0625\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631\u060c \u0644\u062a\u0635\u0644 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0646\u062d\u0648 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0645\u0645\u062a\u062f\u0629 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628.\n\u0643\u0631\u0631 \u062d\u0631\u0643\u0629 \u0627\u0644\u0627\u0646\u062d\u0646\u0627\u0621 \u062c\u0646\u0628\u064b\u0627 \u0625\u0644\u0649 \u062c\u0646\u0628 \u0644\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3213","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques","hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3213-WCAvOfC.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3213-WCAvOfC.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f61227e5-45b4-5bb9-8763-f3a97bacd9a1","source_id":"0725","name_en":"single arm push-up","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 \u0628\u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629","match_names":["single arm push-up"],"muscle":"chest","equipment":"bodyweight","aliases":["single arm push-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.\nEngage your core and lower your body towards the ground by bending your elbows, keeping your back straight.\nAs you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.\nPush through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.\nRepeat the movement, alternating the arm you extend with each repetition.","steps_ar":"\u0627\u0628\u062f\u0623 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0648\u0636\u0639 \u0625\u062d\u062f\u0649 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0646\u0637\u0627\u0642 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u062c\u0630\u0639\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0639\u0646\u062f\u0645\u0627 \u062a\u062e\u0641\u0636 \u0646\u0641\u0633\u0643\u060c \u0642\u0645 \u0628\u062a\u062d\u0648\u064a\u0644 \u0648\u0632\u0646\u0643 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0645\u0639\u0627\u0643\u0633 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0645\u062f\u0647\u0627 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628.\n\u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0635\u062f\u0631\u0643 \u0648\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0644\u0631\u0641\u0639 \u062c\u0633\u0645\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0628\u064a\u0646\u0645\u0627 \u062a\u0642\u0648\u0645 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0646\u0641\u0633\u0647 \u0628\u062e\u0641\u0636 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0645\u0645\u062f\u0648\u062f\u0629 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0645\u0639 \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u062a\u064a \u062a\u0645\u062f\u0647\u0627 \u0645\u0639 \u0643\u0644 \u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0725","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0725-MUic5zN.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0725-MUic5zN.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"178c66dc-73e3-5f64-8f10-50b2bf538c73","source_id":"3645","name_en":"single leg bridge with outstretched leg","name_ar":"\u062c\u0633\u0631 \u0628\u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629 \u0645\u0639 \u0633\u0627\u0642 \u0645\u0645\u062f\u0648\u062f\u0629","match_names":["single leg bridge with outstretched leg"],"muscle":"glutes","equipment":"bodyweight","aliases":["single leg bridge with outstretched leg"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Lie on your back with your knees bent and feet flat on the ground.\nExtend one leg straight out in front of you.\nEngage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.\nHold for a moment at the top, then slowly lower your hips back down to the starting position.\nRepeat for the desired number of repetitions, then switch legs.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0645\u062f \u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0623\u0645\u0627\u0645\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0644\u062a\u0634\u0643\u0644 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0643\u0628\u062a\u064a\u0643 \u0625\u0644\u0649 \u0643\u062a\u0641\u064a\u0643.\n\u0627\u0646\u062a\u0638\u0631 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0648\u0631\u0643\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3645","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3645-rmEukuS.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3645-rmEukuS.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"12796e9f-129a-5e64-8184-418c03390a96","source_id":"0727","name_en":"single leg calf raise (on a dumbbell)","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0633\u0627\u0642 \u0628\u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629 (\u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644)","match_names":["single leg calf raise (on a dumbbell)"],"muscle":"calves","equipment":"dumbbell","aliases":["single leg calf raise (on a dumbbell)"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet hip-width apart and hold a dumbbell in one hand.\nLift one foot off the ground and balance on the other foot.\nSlowly raise your heel as high as possible, using your calf muscles.\nPause for a moment at the top, then slowly lower your heel back down.\nRepeat for the desired number of repetitions, then switch to the other leg.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643\u060c \u0648\u0627\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u064a\u062f \u0648\u0627\u062d\u062f\u0629.\n\u0627\u0631\u0641\u0639 \u0642\u062f\u0645\u064b\u0627 \u0648\u0627\u062d\u062f\u0629 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0627\u0632\u0646 \u0641\u064a \u0627\u0644\u0642\u062f\u0645 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0631\u0641\u0639 \u0643\u0639\u0628\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0633\u0627\u0642.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0643\u0639\u0628\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0727","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["ankles","feet"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0727-fKZgDEO.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0727-fKZgDEO.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"21384c12-913f-5818-8775-b9c0b1814cfd","source_id":"0730","name_en":"single leg platform slide","name_ar":"\u0634\u0631\u064a\u062d\u0629 \u0645\u0646\u0635\u0629 \u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629","match_names":["single leg platform slide"],"muscle":"hamstrings","equipment":"bodyweight","aliases":["single leg platform slide"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by standing with one foot on a platform or slide board.\nBend your knee slightly and slide the foot on the platform backward, extending your leg.\nKeep your core engaged and maintain a straight posture throughout the movement.\nSlowly return to the starting position by sliding your foot back to the initial position.\nRepeat the movement for the desired number of repetitions, then switch legs.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0628\u0642\u062f\u0645 \u0648\u0627\u062d\u062f\u0629 \u0639\u0644\u0649 \u0645\u0646\u0635\u0629 \u0623\u0648 \u0644\u0648\u062d \u0645\u0646\u0632\u0644\u0642.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b \u0648\u062d\u0631\u0643 \u0642\u062f\u0645\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u0635\u0629 \u0644\u0644\u062e\u0644\u0641\u060c \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0646\u0634\u063a\u0627\u0644 \u0642\u0644\u0628\u0643 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0645\u0633\u062a\u0642\u064a\u0645\u0629 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u062d\u0631\u064a\u0643 \u0642\u062f\u0645\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0623\u0648\u0644\u064a.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0730","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["glutes","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0730-LNE3wfo.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0730-LNE3wfo.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"274eb410-a76e-58b6-852c-fb5906536325","source_id":"1759","name_en":"single leg squat (pistol) male","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0628\u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629 (\u0627\u0644\u0645\u0633\u062f\u0633) \u0630\u0643\u0631","match_names":["single leg squat (pistol) male"],"muscle":"glutes","equipment":"bodyweight","aliases":["single leg squat (pistol) male"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and arms extended in front of you.\nLift your right foot off the ground and extend it forward.\nSlowly lower your body down by bending your left knee and pushing your hips back.\nKeep your chest up and your back straight as you lower yourself down.\nLower until your left thigh is parallel to the ground, or as low as you can comfortably go.\nPause for a moment at the bottom, then push through your left heel to return to the starting position.\nRepeat for the desired number of repetitions, then switch legs.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0643\u062a\u0641\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0627\u0631\u0641\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u062f\u0647\u0627 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0628\u064a\u0646\u0645\u0627 \u062a\u0646\u0632\u0644 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0627\u062e\u0641\u0636 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636\u060c \u0623\u0648 \u0645\u0646\u062e\u0641\u0636\u064b\u0627 \u0642\u062f\u0631 \u0627\u0644\u0625\u0645\u0643\u0627\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0628\u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1759","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1759-nqs5HGV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1759-nqs5HGV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8fc928d2-a934-5413-8c3e-f937b4035ebd","source_id":"1489","name_en":"sissy squat","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0633\u064a\u0633\u064a","match_names":["sissy squat"],"muscle":"quads","equipment":"bodyweight","aliases":["sissy squat"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your toes pointing slightly outward.\nHold onto a stable object for balance if needed.\nSlowly lower your body by bending your knees and leaning back, keeping your torso upright.\nContinue lowering until your thighs are parallel to the ground or as far as you can comfortably go.\nPause for a moment, then push through your heels to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0646\u062d\u0648 \u0627\u0644\u062e\u0627\u0631\u062c \u0642\u0644\u064a\u0644\u0627\u064b.\n\u062a\u0645\u0633\u0643 \u0628\u062c\u0633\u0645 \u062b\u0627\u0628\u062a \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062a\u0648\u0627\u0632\u0646 \u0625\u0630\u0627 \u0644\u0632\u0645 \u0627\u0644\u0623\u0645\u0631.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0627\u0644\u0627\u0646\u062d\u0646\u0627\u0621 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062c\u0630\u0639\u0643 \u0641\u064a \u0648\u0636\u0639 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636 \u0623\u0648 \u0625\u0644\u0649 \u0623\u0642\u0635\u0649 \u062d\u062f \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1489","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["calves","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1489-xdYPUtE.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1489-xdYPUtE.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}}]'::jsonb)
AS r(id uuid,source_id text,name_en text,name_ar text,match_names jsonb,muscle text,equipment text,aliases jsonb,logging_mode text,load_convention text,guidance jsonb);
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM catalogue_input r WHERE (SELECT count(*) FROM public.exercises e WHERE
   (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
   OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment))>1)
 THEN RAISE EXCEPTION 'Ambiguous catalogue match; review before importing'; END IF;
END $$;
INSERT INTO public.exercises(id,name_en,name_ar,muscle,equipment,equipment_tags,aliases,logging_mode,load_convention,guidance,editorial_status)
SELECT coalesce((SELECT e.id FROM public.exercises e WHERE
  (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
  OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment)),r.id),
 r.name_en,r.name_ar,r.muscle,r.equipment,ARRAY[r.equipment],ARRAY(SELECT jsonb_array_elements_text(r.aliases)),r.logging_mode,r.load_convention,r.guidance,'needs_review'
FROM catalogue_input r
ON CONFLICT(id) DO UPDATE SET
 name_ar=coalesce(nullif(public.exercises.name_ar,''),EXCLUDED.name_ar),
 aliases=ARRAY(SELECT DISTINCT value FROM unnest(public.exercises.aliases || EXCLUDED.aliases) value ORDER BY value),
 guidance=EXCLUDED.guidance || public.exercises.guidance
WHERE public.exercises.editorial_status<>'reviewed'
 AND (public.exercises.guidance->'text_source' IS NULL OR
  (public.exercises.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND public.exercises.guidance->'text_source'->>'exercise_id'=EXCLUDED.guidance->'text_source'->>'exercise_id'));
COMMIT;
